using NUnit.Framework;using UnityEngine;using VContainer;using VContainer.Unity;using Janseon.Core.Data;using Janseon.Core.Battle.Contracts;using Janseon.Data.Authoring;using Janseon.Data.Repositories;using Janseon.Data.Validation;
namespace Janseon.Foundation.Tests { public sealed class Area1VContainerBindingTests { static GameDataCatalogAsset Base(){var c=ScriptableObject.CreateInstance<GameDataCatalogAsset>();c.cards=new CardDefinitionAsset[6];string[] ids={"guard-shieldwall","encourage-morale","pincer-focus","mobility-regroup","supply-heal","passage-retreat"};for(int i=0;i<6;i++){c.cards[i]=ScriptableObject.CreateInstance<CardDefinitionAsset>();c.cards[i].stableId="card."+ids[i];c.cards[i].coreCardId=ids[i];c.cards[i].kind=i<4?CardKind.Character:CardKind.Stronghold;c.cards[i].rechargeTicks=new[]{300,600,450,600,900,750}[i];c.cards[i].effect=new[]{-3,10,1,1,5,1}[i];c.cards[i].effectKey=new[]{"front_damage","morale","front_damage","cardinal_reposition","front_heal","retreat"}[i];}c.unitRoles=new UnitRoleDefinitionAsset[3];string[] roles={"근위","돌격","궁수"};for(int i=0;i<3;i++){c.unitRoles[i]=ScriptableObject.CreateInstance<UnitRoleDefinitionAsset>();c.unitRoles[i].stableId="unit.role."+new[]{"guard","assault","archer"}[i];c.unitRoles[i].coreRole=roles[i];c.unitRoles[i].maxHp=new[]{30,20,14}[i];c.unitRoles[i].power=new[]{4,6,3}[i];c.unitRoles[i].rangeMin=1;c.unitRoles[i].rangeMax=new[]{1,1,3}[i];c.unitRoles[i].moveTicksPerCell=10;c.unitRoles[i].attackCooldownTicks=30;}var f=ScriptableObject.CreateInstance<FormationDefinitionAsset>();f.stableId="formation.default-3x3";f.rowCount=3;f.columnCount=3;f.slots=new FormationSlotDefinition[6];for(int i=0;i<6;i++)f.slots[i]=new FormationSlotDefinition{roleStableId=c.unitRoles[i/2].stableId,row=i/2,column=i%2-1,facing=Janseon.Core.CardinalDirection.East};c.formations=new[]{f};c.stations=new StationDefinitionAsset[3];string[] names={"yeongdeungpo","sindorim","guro"},core={"Yeongdeungpo","Sindorim","Guro"};string[][] ns={new[]{"station.sindorim"},new[]{"station.yeongdeungpo","station.guro"},new[]{"station.sindorim"}};for(int i=0;i<3;i++){c.stations[i]=ScriptableObject.CreateInstance<StationDefinitionAsset>();c.stations[i].stableId="station."+names[i];c.stations[i].coreStationId=core[i];c.stations[i].neighbors=ns[i];}c.contentSchema=1;c.contentVersion="area1-static-content-v1";c.fingerprintVersion="content-fingerprint-v1";return c;} sealed class FakeCards:IReadOnlyCardCatalog { public System.Collections.Generic.IReadOnlyList<CardCatalogItem> All{get;}=new System.Collections.Generic.List<CardCatalogItem>();public bool TryGet(string id,out CardCatalogItem item){item=null;return false;}public bool TryGetByCoreId(string id,out CardCatalogItem item){item=null;return false;} } [Test]public void FoundationScope_ResolvesOneSingletonPerReadOnlyContract(){var asset=Base();var index=GameDataCatalogIndexBuilder.Build(asset);var scope=LifetimeScope.Create(b=>{b.RegisterInstance(index);b.Register<CardCatalogRepository>(Lifetime.Singleton).As<IReadOnlyCardCatalog>();b.Register<UnitRoleCatalogRepository>(Lifetime.Singleton).As<IReadOnlyUnitRoleCatalog>();b.Register<FormationCatalogRepository>(Lifetime.Singleton).As<IReadOnlyFormationCatalog>();b.Register<StationCatalogRepository>(Lifetime.Singleton).As<IReadOnlyStationCatalog>();});var first=scope.Container.Resolve<IReadOnlyCardCatalog>();var second=scope.Container.Resolve<IReadOnlyCardCatalog>();Assert.AreSame(first,second);var fake=new FakeCards();var child=scope.CreateChild(b=>b.RegisterInstance<IReadOnlyCardCatalog>(fake));Assert.AreSame(fake,child.Container.Resolve<IReadOnlyCardCatalog>());Assert.AreSame(first,scope.Container.Resolve<IReadOnlyCardCatalog>());var sibling=scope.CreateChild();Assert.AreSame(first,sibling.Container.Resolve<IReadOnlyCardCatalog>());/* Duplicate registrations are prevented by review/rule, not asserted on VContainer behavior. */ var rawScope=LifetimeScope.Create(b=>b.RegisterInstance(index));Assert.Throws<VContainerException>(()=>rawScope.Container.Resolve<GameDataCatalogAsset>());rawScope.Dispose();child.Dispose();sibling.Dispose();scope.Dispose();Object.DestroyImmediate(asset);}}}
